import{_ as s,o as e,c as i,am as n}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"动画学Redis进阶内容","description":"","frontmatter":{"title":"动画学Redis进阶内容","excerpt":"B 站的一个视频，讲的还不错，建议看下","date":"2024-05-09 16:51:54","updated":"2024-05-09 16:51:54"},"headers":[],"relativePath":"数据库/NoSQL数据库/技术栈 Redis/动画学Redis进阶内容.md","filePath":"数据库/NoSQL数据库/技术栈 Redis/动画学Redis进阶内容.md","lastUpdated":null}'),t={name:"数据库/NoSQL数据库/技术栈 Redis/动画学Redis进阶内容.md"};function l(o,a,r,p,h,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<p>视频地址： <a href="https://www.bilibili.com/video/BV1xm42177Fq" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1xm42177Fq</a></p><h3 id="实现分布式全局id、浏览数、值缓存、分布式session" tabindex="-1">实现分布式全局ID、浏览数、值缓存、分布式session <a class="header-anchor" href="#实现分布式全局id、浏览数、值缓存、分布式session" aria-label="Permalink to &quot;实现分布式全局ID、浏览数、值缓存、分布式session&quot;">​</a></h3><h4 id="stirng-应用-值缓存" tabindex="-1">Stirng 应用-值缓存 <a class="header-anchor" href="#stirng-应用-值缓存" aria-label="Permalink to &quot;Stirng 应用-值缓存&quot;">​</a></h4><p>举一个例子，存在一个树结构【角色 → 人物】的一个树结构</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509165650.png" alt="image.png|300"></p><p>考虑将列表内容存入到 Redis 中，</p><ul><li>将查询结果反序列化为一个 Json 数据，存入到 Redis 中</li><li>作为一个查询缓存</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509165828.png" alt="image.png"></p><h4 id="三级下拉框" tabindex="-1">三级下拉框 <a class="header-anchor" href="#三级下拉框" aria-label="Permalink to &quot;三级下拉框&quot;">​</a></h4><p>根据上文，这里扩展一下，一般来说，下拉框数据也可以使用 hash 结构，数据量少的话可以使用 string 类型。</p><p>Hash结构，以 国家、省份、城市 为示例</p><p>一级</p><p>键 countries 值 列表《国家ID，名称 》</p><p>二级：</p><p>键 privinces:国家ID， 值 列表《省份ID，名称 》</p><p>三级：</p><p>键 privinces:省份ID， 值 列表《城市ID，名称 》</p><h4 id="stirng应用-浏览数" tabindex="-1">Stirng应用-浏览数 <a class="header-anchor" href="#stirng应用-浏览数" aria-label="Permalink to &quot;Stirng应用-浏览数&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509165933.png" alt="image.png"></p><h4 id="stirng应用-分布式系统全局-id" tabindex="-1">Stirng应用-分布式系统全局 ID <a class="header-anchor" href="#stirng应用-分布式系统全局-id" aria-label="Permalink to &quot;Stirng应用-分布式系统全局 ID&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509170035.png" alt="image.png"></p><p>扩展：在高并发情况下，每次创建一个订单，就需要和 Redis 交互一次，对于 redis 的压力会非常大的</p><p>如何优化这个场景？</p><p>我们可以每一次取 1000 个订单 ID（各服务取1000个 ID 备用）；</p><p>每当订单服务需要创建订单的时候，就自增一次服务器内部的这个自增ID，直到 服务器内部的这个备用 ID 都用光了，再去 redis 中取 1000 个订单ID</p><p>可以使用命令 incr key count 来实现这个操作</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509170541.png" alt="image.png"></p><p>命令</p><h4 id="分布式-session" tabindex="-1">分布式 session <a class="header-anchor" href="#分布式-session" aria-label="Permalink to &quot;分布式 session&quot;">​</a></h4><p>将 session 存入到 redis 中，通过 session ID 来获取 session 信息，实现跨服务器访问应用服务（共享 session）</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509170929.png" alt="image.png"></p><h3 id="redis分布式锁-锁订阅、锁续期、lua原子执行原理、顺便讲sync锁升级" tabindex="-1">Redis分布式锁，锁订阅、锁续期、Lua原子执行原理、顺便讲Sync锁升级 <a class="header-anchor" href="#redis分布式锁-锁订阅、锁续期、lua原子执行原理、顺便讲sync锁升级" aria-label="Permalink to &quot;Redis分布式锁，锁订阅、锁续期、Lua原子执行原理、顺便讲Sync锁升级&quot;">​</a></h3><h4 id="可重入锁" tabindex="-1">可重入锁 <a class="header-anchor" href="#可重入锁" aria-label="Permalink to &quot;可重入锁&quot;">​</a></h4><p>单体，JVM 进行通过加锁 synchronized</p><p>跨进程：Redis 分布式锁</p><p>setnx 设置会返回一个响应，如果存在再设置</p><p>问题</p><ul><li>可重入锁设置</li><li>使用 hash 结构解决重入锁问题 <ul><li>hash 的 key1：锁的名称</li><li>hash 的 key2：锁的持有者线程 UUID</li><li>hash 的 value：重入次数</li></ul></li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509190558.png" alt="image.png"></p><p>复习一个基础概念：redis 一般是键值对结构，键始终是字符串，值有多种类型，比如 set、string、list、zset、hash 等。</p><p>这里的可重入锁的 key 为 锁名称， value 是 一个 hash 结构，结构为：锁持有者，重入计数 （计数器结构）</p><p>由于是 hash 结构，因此这里不能使用 setnx 命令，而是使用的 lua 命令</p><p>redisson 的部分代码</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    &lt;T&gt; RFuture&lt;T&gt; tryLockInnerAsync(long waitTime, long leaseTime, TimeUnit unit, long threadId, RedisStrictCommand&lt;T&gt; command) {</span></span>
<span class="line"><span>        return this.commandExecutor.syncedEval(this.getRawName(), LongCodec.INSTANCE, command, &quot;if ((redis.call(&#39;exists&#39;, KEYS[1]) == 0) or (redis.call(&#39;hexists&#39;, KEYS[1], ARGV[2]) == 1)) then redis.call(&#39;hincrby&#39;, KEYS[1], ARGV[2], 1); redis.call(&#39;pexpire&#39;, KEYS[1], ARGV[1]); return nil; end; return redis.call(&#39;pttl&#39;, KEYS[1]);&quot;, Collections.singletonList(this.getRawName()), new Object[]{unit.toMillis(leaseTime), this.getLockName(threadId)});</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>这条Lua脚本的目的是原子性地处理一个计数器，通常用于实现锁机制。它检查一个锁键是否存在或一个特定的锁标识是否存在，如果满足条件，则递增锁标识的计数器，并设置或更新键的过期时间。如果计数器递增成功，脚本返回<code>nil</code>；如果没有递增（即锁已被其他客户端持有），则返回当前锁的剩余过期时间。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509200158.png" alt="image.png"></p><p>每当我们每次重入一次，则计数 + 1，如果释放锁，计数 - 1</p><h4 id="释放锁" tabindex="-1">释放锁 <a class="header-anchor" href="#释放锁" aria-label="Permalink to &quot;释放锁&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240509200455.png" alt="image.png"></p><h4 id="锁订阅" tabindex="-1">锁订阅 <a class="header-anchor" href="#锁订阅" aria-label="Permalink to &quot;锁订阅&quot;">​</a></h4><h4 id="锁续期" tabindex="-1">锁续期 <a class="header-anchor" href="#锁续期" aria-label="Permalink to &quot;锁续期&quot;">​</a></h4><h4 id="lua原子执行原理" tabindex="-1">Lua原子执行原理 <a class="header-anchor" href="#lua原子执行原理" aria-label="Permalink to &quot;Lua原子执行原理&quot;">​</a></h4><h4 id="sync锁升级" tabindex="-1">Sync锁升级 <a class="header-anchor" href="#sync锁升级" aria-label="Permalink to &quot;Sync锁升级&quot;">​</a></h4><ul><li>锁升级过程 <ul><li>偏向锁 单线程</li><li>轻量级锁 多线程交互持有</li><li>重量级锁 锁竞争，发生竞争的判断依据就是根据线程使用CAS指令加锁或者解锁的时候是否失败来决定的</li></ul></li><li>重量级锁实现原理 <ul><li>sychronized底层是 monitor(监视器) 实现的，</li><li>monitor 包含三个东西：owner、entrylist、waitset，另外monitor是属于锁对象的，mark word和monitor都是对象头的一部分。</li></ul></li></ul><h3 id="redis红锁-主从情况下问题、持久化不彻底问题" tabindex="-1">Redis红锁，主从情况下问题、持久化不彻底问题 <a class="header-anchor" href="#redis红锁-主从情况下问题、持久化不彻底问题" aria-label="Permalink to &quot;Redis红锁，主从情况下问题、持久化不彻底问题&quot;">​</a></h3><h3 id="redis消息队列-list-发布订阅-stream实现及如何保证可靠性-消息确认机制" tabindex="-1">Redis消息队列，List，发布订阅，Stream实现及如何保证可靠性，消息确认机制 <a class="header-anchor" href="#redis消息队列-list-发布订阅-stream实现及如何保证可靠性-消息确认机制" aria-label="Permalink to &quot;Redis消息队列，List，发布订阅，Stream实现及如何保证可靠性，消息确认机制&quot;">​</a></h3><h4 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h4><p>通常三种方式来实现消息队列</p><ul><li>1、List</li><li>2、发布订阅</li><li>3、Stream (Redis 5.0 中加入的数据结构)</li></ul><h5 id="通过-list-来实现消息队列" tabindex="-1">通过 List 来实现消息队列 <a class="header-anchor" href="#通过-list-来实现消息队列" aria-label="Permalink to &quot;通过 List 来实现消息队列&quot;">​</a></h5><p>使用 Redis 的列表（list）数据结构来创建一个消息队列。列表的两端分别代表队列的头部（消费者读取端）和尾部（生产者写入端）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 使用 RPUSH 命令将消息添加到队列尾部</span></span>
<span class="line"><span>127.0.0.1:6379&gt; RPUSH order_queue &quot;order_data_1&quot;</span></span>
<span class="line"><span># 使用 LPOP 命令从队列头部读取消息</span></span>
<span class="line"><span>127.0.0.1:6379&gt; LPOP order_queue</span></span></code></pre></div><p>常用命令</p><ul><li>RPUSH：添加元素到列表的尾部（右边）</li><li>LPOP：移除并返回列表头部（左边）的元素</li><li>BLPOP：BLPOP 是 LPOP 的阻塞版本，它移除并返回列表头部的元素。如果没有元素可供移除，BLPOP 会阻塞直到有新元素被添加或者超时</li></ul><p>消息队列实现： LPUSH + RPOP 或者 RPUSH + LPOP ；一般会使用阻塞方式读取消息：BLPOP 或者 BRPOP</p><h5 id="基于发布订阅实现消息队列" tabindex="-1">基于发布订阅实现消息队列 <a class="header-anchor" href="#基于发布订阅实现消息队列" aria-label="Permalink to &quot;基于发布订阅实现消息队列&quot;">​</a></h5><p>使用 Redis 的发布订阅会有 4 个基础概念：</p><ol><li><strong>发布者（Publisher）</strong>：负责发送消息的客户端或服务。</li><li><strong>订阅者（Subscriber）</strong>：负责接收消息的客户端或服务。</li><li><strong>频道（Channel）</strong>：消息发布的目的地，订阅者监听这些频道以接收消息。</li><li><strong>模式（Pattern）</strong>：一种基于通配符的频道匹配规则，允许订阅者订阅符合特定模式的频道。</li></ol><p>使用示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#订阅消息，可以多个订阅者订阅一个频道</span></span>
<span class="line"><span>127.0.0.1:6379&gt; SUBSCRIBE mychannel</span></span>
<span class="line"><span>#发布消息，发布者使用 \`PUBLISH\` 命令向一个或多个频道发送消息。</span></span>
<span class="line"><span>127.0.0.1:6379&gt; PUBLISH mychannel &quot;Hello, Redis!&quot;</span></span></code></pre></div><p>订阅者在接收到消息后，可以根据业务逻辑进行处理。</p><p>订阅者还可以使用 <code>PSUBSCRIBE</code> 命令订阅符合特定模式的频道，这在需要订阅多个类似频道时非常有用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>127.0.0.1:6379&gt; PSUBSCRIBE mychannel:*</span></span></code></pre></div><h5 id="通过-stream-实现消息队列" tabindex="-1">通过 stream 实现消息队列 <a class="header-anchor" href="#通过-stream-实现消息队列" aria-label="Permalink to &quot;通过 stream 实现消息队列&quot;">​</a></h5><p>基本概念</p><ol><li><strong>Stream</strong>：Redis Streams 是一个消息队列，它是一个包含多个消息的序列。</li><li><strong>消息（Message）</strong>：Stream 中的每个元素称为消息，每个消息都有一个唯一的 ID。</li><li><strong>消费者组（Consumer Group）</strong>：消费者组是一组消费者，它们共享对 Stream 的访问，可以并行处理消息。</li><li><strong>XADD</strong>：用于向 Stream 添加消息的命令。</li><li><strong>XREAD</strong>：用于从 Stream 读取消息的命令。</li><li><strong>XACK</strong>：用于确认消息已经被处理的命令。</li><li><strong>XGROUP</strong>：用于创建消费者组的命令。</li><li><strong>XPENDING</strong>：查看消费者组未处理的消息数量的命令。</li></ol><p>使用示例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#创建 Stream，使用 \`XADD\` 命令向 Stream 添加消息。</span></span>
<span class="line"><span>127.0.0.1:6379&gt; XADD mystream * myfield1 &quot;Hello&quot; myfield2 &quot;World&quot;</span></span>
<span class="line"><span>#创建消费者组：使用 \`XGROUP\` 命令创建一个消费者组</span></span>
<span class="line"><span>127.0.0.1:6379&gt; XGROUP CREATE mystream mygroup $ MKSTREAM</span></span>
<span class="line"><span>#从消费者组中读取消息，消费者使用 \`XREADGROUP\` 命令从消费者组中读取消息。</span></span>
<span class="line"><span>127.0.0.1:6379&gt; XREADGROUP GROUP mygroup consumer1 COUNT 1 STREAMS mystream &gt;</span></span>
<span class="line"><span>#消息确认，消费者处理完消息后，使用 \`XACK\` 命令确认消息。</span></span>
<span class="line"><span>127.0.0.1:6379&gt; XACK mystream mygroup &lt;message_id&gt;</span></span></code></pre></div><p>代码示例略过</p><h3 id="缓存击穿、穿透、雪崩、布隆过滤器的实现" tabindex="-1">缓存击穿、穿透、雪崩、布隆过滤器的实现 <a class="header-anchor" href="#缓存击穿、穿透、雪崩、布隆过滤器的实现" aria-label="Permalink to &quot;缓存击穿、穿透、雪崩、布隆过滤器的实现&quot;">​</a></h3><h4 id="过期时间" tabindex="-1">过期时间 <a class="header-anchor" href="#过期时间" aria-label="Permalink to &quot;过期时间&quot;">​</a></h4><p>一般是缓存数据设置过期时间 + 设置淘汰策略</p><p>当热点数据设置有效时间后，会采用预热（应用启动时加载），写入时续期，访问时续期，或者定时任务执行（为即将过期的热点数据执行续期操作）；</p><p>通过设置有效时间，可以有效过滤掉冷门时间，减少 redis 中的使用内存。</p><h4 id="缓存击穿" tabindex="-1">缓存击穿 <a class="header-anchor" href="#缓存击穿" aria-label="Permalink to &quot;缓存击穿&quot;">​</a></h4><p>解决方案</p><ul><li>1、热点数据不设置过期时间</li><li>2、互斥锁 <ul><li>使用分布式锁</li></ul></li></ul><h4 id="缓存雪崩" tabindex="-1">缓存雪崩 <a class="header-anchor" href="#缓存雪崩" aria-label="Permalink to &quot;缓存雪崩&quot;">​</a></h4><h3 id="为何延时双删、删除重试" tabindex="-1">为何延时双删、删除重试 <a class="header-anchor" href="#为何延时双删、删除重试" aria-label="Permalink to &quot;为何延时双删、删除重试&quot;">​</a></h3>`,89)])])}const g=s(t,[["render",l]]);export{u as __pageData,g as default};
